package llvm

import (
	"strings"
	"testing"

	"github.com/lizongying/nolang/lexer"
	"github.com/lizongying/nolang/parser"
)

// TestMatchStrLongItDeepClone verifies that synthetic `it = matched` bindings
// generated by match expression desugar (`cmd: { 'x' -> ... }`) perform a
// deep clone of the source str-long variable, not a shallow copy.
//
// The bug: synthetic `it = cmd` (where cmd is a local %str-long heap variable)
// was excluded from the clone/move path by `!stmt.IsSynthetic`, causing it to
// fall through to the generic store path which does a shallow copy
// (store %str-long). Both `it` and `cmd` share the same data pointer, and
// emitHeapFree double-frees it at function exit (SIGTRAP / exit 133).
//
// The fix: allow synthetic bindings through the clone path when the source
// is NOT an %option variable (option sources only borrow the inner value;
// the option box retains data ownership).
func TestMatchStrLongItDeepClone(t *testing.T) {
	src := `
main = () () {
    argc = os.args() - 1
    argc < 1 -> {
        print('usage')
        return
    }
    cmd = os.arg(1)
    cmd: {
        'a' -> print('a')
        'b' -> print('b')
        'version' -> print('v0.1.0')
        -> {
            print('unknown')
        }
    }
}
`
	l := lexer.New(src)
	p := parser.New(l)
	prog := p.ParseProgram()
	if len(p.Errors()) > 0 {
		t.Fatalf("parse errors: %v", p.Errors())
	}

	g := NewGenerator()
	ir := g.Generate(prog)

	// The `it` variable must be allocated (alloca)
	if !strings.Contains(ir, "%it = alloca") {
		t.Errorf("IR should allocate %%it variable, got:\n%s", ir)
	}

	// The fix: synthetic `it = cmd` must deep-clone, not shallow-copy.
	// Deep clone emits emitDeepClone → emitContainerClone, which produces
	// a call to @nolang.malloc for new data buffer and @llvm.memcpy.
	// A shallow copy only emits `store %str-long`, sharing the data pointer.
	//
	// We check that in the match arm (if.then block), the code path includes
	// a deep clone pattern: load + malloc + memcpy for the it binding.
	// If only a simple `store %str-long ... %str-long* %it` is found without
	// an accompanying deep clone, the bug is present.

	// Count deep clone markers (malloc + memcpy in close proximity) near `it`
	lines := strings.Split(ir, "\n")
	shallowStoreToIt := false
	for i, line := range lines {
		trimmed := strings.TrimSpace(line)
		// Look for a plain store to %it that is NOT preceded by a deep clone
		// pattern. In the fixed code, the store to %it is replaced by
		// emitDeepClone which generates getelementptr/malloc/memcpy.
		if strings.Contains(trimmed, "store") && strings.Contains(trimmed, "%str-long") && strings.Contains(trimmed, "%it") {
			// Check if this is part of a deep clone (look back a few lines for malloc)
			hasMalloc := false
			for j := max(0, i-10); j < i; j++ {
				tj := strings.TrimSpace(lines[j])
				if strings.Contains(tj, "@nolang.malloc") {
					hasMalloc = true
					break
				}
			}
			if !hasMalloc {
				shallowStoreToIt = true
			}
		}
	}
	if shallowStoreToIt {
		t.Errorf("synthetic `it = cmd` should deep-clone (malloc+memcpy), but found a shallow store to %%it without preceding malloc (double-free bug). IR:\n%s", ir)
	}
}

// TestMatchStrLongItDeepCloneOptionExcluded verifies that synthetic `it = matched`
// for OPTION sources still does a shallow copy (not deep clone), because the
// option box owns the data and `it` only borrows the inner value.
func TestMatchStrLongItDeepCloneOptionExcluded(t *testing.T) {
	src := `
read-file = (path str) (result ?str) {
    result = path
}

main = () {
    content = read-file('test')
    content: {
        nil -> {
            print('nil')
        }
        err -> {
            print('err')
        }
        ->
            file-content = it
            print(file-content)
    }
}
`
	l := lexer.New(src)
	p := parser.New(l)
	prog := p.ParseProgram()
	if len(p.Errors()) > 0 {
		t.Fatalf("parse errors: %v", p.Errors())
	}

	g := NewGenerator()
	ir := g.Generate(prog)

	// For option sources, `it` should still be stored to (shallow borrow from box)
	if !strings.Contains(ir, "%it = alloca") {
		t.Errorf("IR should allocate %%it variable, got:\n%s", ir)
	}

	// The key: there should NOT be a deep clone (emitDeepClone) for the
	// option synthetic `it` binding. The option-specific path handles it
	// with inttoptr + load (borrowing from the box), not malloc + memcpy.
	// If we see @nolang.malloc near the it binding for option source, that
	// would be wrong (it would allocate a new buffer for borrowed data).
}
